// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Gap-analysis B4: the kernel EXISTS/NOT-EXISTS witness must not drop correlation when the correlated column is
 * OPTIONAL-produced through a BIND alias. The suspected failure: {@code witnessOperand} returns null for the alias, and
 * lowering proceeds with an existential fresh column — EXISTS then tests "the subject has <em>any</em> object" instead
 * of "the subject has {@code ?x}'s value", keeping rows whose bound alias does not match (and NOT EXISTS removing too
 * much). s2 is the discriminating row: its optional value (7) differs from its witness object (9), so correlated EXISTS
 * drops it while the existential reading keeps it. These run with the codegen rung pinned ON so the kernel is eligible;
 * whether it claims the plan is the arbiter's call, so the tests assert engine parity, not engagement.
 */
public class LmdbNativeKernelWitnessCorrelationTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String JANINO_FLAG = "rdf4j.lmdb.janinoCodegen.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private String previousJanino;

	@BeforeEach
	public void setUp() {
		previousJanino = System.getProperty(JANINO_FLAG);
		System.setProperty(JANINO_FLAG, "true");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI a = vf.createIRI(EX, "a");
			IRI opt = vf.createIRI(EX, "opt");
			IRI p = vf.createIRI(EX, "p");
			// s1: alias 5, witness 5 -> correlated EXISTS keeps it
			conn.add(vf.createIRI(EX, "s1"), a, vf.createLiteral("l1"));
			conn.add(vf.createIRI(EX, "s1"), opt, vf.createLiteral(5));
			conn.add(vf.createIRI(EX, "s1"), p, vf.createLiteral(5));
			// s2: alias 7, witness 9 -> correlated EXISTS drops it; the existential bug keeps it
			conn.add(vf.createIRI(EX, "s2"), a, vf.createLiteral("l2"));
			conn.add(vf.createIRI(EX, "s2"), opt, vf.createLiteral(7));
			conn.add(vf.createIRI(EX, "s2"), p, vf.createLiteral(9));
			// s3: no optional -> alias unbound -> EXISTS { ?s <p> ?x } is existential for real
			conn.add(vf.createIRI(EX, "s3"), a, vf.createLiteral("l3"));
			conn.add(vf.createIRI(EX, "s3"), p, vf.createLiteral(1));
		}
	}

	@AfterEach
	public void tearDown() {
		if (previousJanino == null) {
			System.clearProperty(JANINO_FLAG);
		} else {
			System.setProperty(JANINO_FLAG, previousJanino);
		}
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void existsOverOptionalProducedBindAliasStaysCorrelated() {
		String query = "SELECT ?s ?x WHERE { ?s <" + EX + "a> ?l"
				+ " OPTIONAL { ?s <" + EX + "opt> ?o } BIND(?o AS ?x)"
				+ " FILTER EXISTS { ?s <" + EX + "p> ?x } } ORDER BY ?s";

		List<String> generic = rows(query, false);
		assertThat(generic)
				.as("interpreted oracle: s1 (alias matches witness) and s3 (unbound alias, existential)")
				.containsExactly("s=http://example.com/s1|x=\"5\"^^<http://www.w3.org/2001/XMLSchema#int>",
						"s=http://example.com/s3");
		assertThat(rows(query, true))
				.as("native EXISTS over the BIND alias must stay correlated — s2's mismatched alias may not survive")
				.isEqualTo(generic);
	}

	@Test
	public void notExistsOverOptionalProducedBindAliasStaysCorrelated() {
		String query = "SELECT ?s ?x WHERE { ?s <" + EX + "a> ?l"
				+ " OPTIONAL { ?s <" + EX + "opt> ?o } BIND(?o AS ?x)"
				+ " FILTER NOT EXISTS { ?s <" + EX + "p> ?x } } ORDER BY ?s";

		List<String> generic = rows(query, false);
		assertThat(generic)
				.as("interpreted oracle: only s2 (alias 7 has no witness 7)")
				.containsExactly("s=http://example.com/s2|x=\"7\"^^<http://www.w3.org/2001/XMLSchema#int>");
		assertThat(rows(query, true))
				.as("native NOT EXISTS over the BIND alias must stay correlated — it may not remove s2")
				.isEqualTo(generic);
	}

	private List<String> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(LmdbNativeKernelWitnessCorrelationTest::render)
					.collect(Collectors.toList());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.filter(name -> !name.equals("l"))
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining("|"));
	}
}
